node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Get flight FLE7F420 (SEA -> SAN)
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id='FLE7F420'\").get();
console.log('=== FLIGHT FLE7F420 (SEA → SAN) ===');
console.log(JSON.stringify(flight, null, 2));

// Get the return flight too
const flight2 = db.prepare(\"SELECT * FROM flights WHERE flight_id='FL84B16B'\").get();
console.log('\n=== FLIGHT FL84B16B (SAN → SEA) ===');
console.log(JSON.stringify(flight2, null, 2));
"

node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Get user details
const user = db.prepare(\"SELECT user_id, name, loyalty_tier, email, payment_methods_json FROM users WHERE user_id='user_fa209a3f'\").get();
console.log('=== USER DETAILS ===');
console.log(JSON.stringify(user, null, 2));

// Check flight statuses on the booked dates
const flight1 = db.prepare(\"SELECT flight_id, dates_json FROM flights WHERE flight_id='FLE7F420'\").get();
const dates1 = JSON.parse(flight1.dates_json);
console.log('\n=== FLE7F420 status on 2026-10-01 ===');
console.log(JSON.stringify(dates1['2026-10-01'], null, 2));

const flight2 = db.prepare(\"SELECT flight_id, dates_json FROM flights WHERE flight_id='FL84B16B'\").get();
const dates2 = JSON.parse(flight2.dates_json);
console.log('\n=== FL84B16B status on 2026-10-05 ===');
console.log(JSON.stringify(dates2['2026-10-05'], null, 2));
"

